const bar=(x,y,w=120,h=42,flip=false,angle=0)=>`<g transform="translate(${x} ${y}) rotate(${angle})">`+rect(-w/2,-h/2,w/2,h,flip?K.blue:K.red,'none',1)+rect(0,-h/2,w/2,h,flip?K.red:K.blue,'none',1)+text(-w/4,7,flip?'S':'N',h*.45,'white')+text(w/4,7,flip?'N':'S',h*.45,'white')+'</g>';
function solenoid(x,y,w=150,h=85,n=9,reverse=false){let s='';for(let i=0;i<n;i++){let xx=x-w/2+i*w/(n-1);s+=path(`M${xx} ${y-h/2}C${xx-22} ${y-h/2} ${xx-22} ${y+h/2} ${xx} ${y+h/2}`, '#9caaab',4)+path(`M${xx} ${y+h/2}C${xx+22} ${y+h/2} ${xx+22} ${y-h/2} ${xx} ${y-h/2}`,K.wire,4);if(i<n-1)s+=line(xx,y+(reverse?-1:1)*h/2,xx+w/(n-1),y-(reverse?-1:1)*h/2,'#95a4a5',1);}return s;}
function compass(x,y,bx,by,r=12,disc=true){const a=Math.atan2(by,bx),l=r*.82;if(disc)return circle(x,y,r,'#fffffff0','#b0c3c2',1)+`<g transform="translate(${x} ${y}) rotate(${a/RAD})"><path d="M${-l} 0L0 -3L0 3Z" fill="${K.blue}"/><path d="M${l} 0L0 -3L0 3Z" fill="${K.red}"/></g>`;return arrow(x-l*Math.cos(a),y-l*Math.sin(a),x+l*Math.cos(a),y+l*Math.sin(a),K.green,1.7);}
