function matrix(field,exclude=()=>false,disc=true,step=36,x0=30,x1=770,y0=35,y1=385){let s='';for(let y=y0;y<=y1;y+=step)for(let x=x0;x<=x1;x+=step){if(exclude(x,y))continue;const b=field(x,y);if(Math.hypot(...b)>1e-15)s+=compass(x,y,...b,11,disc);}return s;}
