install(27,[choice('mode','자기장 표시',['나침반','화살표']),toggle('flip','극 뒤집기')],v=>{const sign=+v.flip?1:-1;return {svg:group('bar-compass-matrix',matrix((x,y)=>dipole(x,y,400,220,sign,0),(x,y)=>Math.abs(x-400)<80&&Math.abs(y-220)<32,!+v.mode,32,25,780,30,410)+bar(400,220,160,54,!!+v.flip)),metrics:[metric('자석 바깥 방향','N극 → S극')],explanation:'나침반 하나하나는 그 자리의 자기장에 정렬합니다. 자석 축 위와 자석 옆의 돌아오는 자기장 방향을 비교하세요.',note:'2차원 투영 자기 쌍극자 근사이며 나침반은 자기장에 영향을 주지 않는 탐침입니다. 바깥 N→S, 내부 S→N의 닫힌 자기장 관계를 유지합니다.'};});
