function shape(o){const {kind}=o;if(kind==='compass')return compass(0,0,1,0,16);if(kind==='bar'||kind==='long')return bar(0,0,kind==='long'?105:74,24,true);if(kind.startsWith('horseshoe')){const rev=kind==='horseshoeR';return path('M35 -24H-27Q-43 -24 -43 0Q-43 24 -27 24H35','#b0babb',19)+line(-8,-24,35,-24,rev?K.blue:K.red,19)+line(-8,24,35,24,rev?K.red:K.blue,19)+text(26,-19,rev?'S':'N',14,'white')+text(26,29,rev?'N':'S',14,'white');}let s=solenoid(0,0,65,34,6,kind==='reverse');if(kind!=='coil')s+=path('M-34 0V38H34V0',K.wire,2)+battery(0,38,false,kind==='reverse',.45);return s;}
