function traces(){let s='';for(const o of objects)for(const [px,py,q] of poles(o)){if(q<0)continue;for(let k=0;k<10;k++){let x=px+12*Math.cos(k*TAU/10),y=py+12*Math.sin(k*TAU/10),d=`M${x} ${y}`;for(let n=0;n<160;n++){const b=field(x,y),l=Math.hypot(...b);if(l<1e-9||x<140||x>790||y<5||y>407)break;x+=4*b[0]/l;y+=4*b[1]/l;d+=`L${x.toFixed(1)} ${y.toFixed(1)}`;if(objects.some(ob=>poles(ob).some(p=>p[2]<0&&Math.hypot(p[0]-x,p[1]-y)<10)))break;}s+=path(d,K.green,1.2);}}return s;}
