function graphSample(u){let p=clamp(u,0,.999999)*4,i=Math.floor(p),f=p-i,s=f*f*(3-2*f),z=graphPoints[i]*(1-s)+graphPoints[i+1]*s,dz=(graphPoints[i+1]-graphPoints[i])*6*f*(1-f)*4/8;return {position:z,velocity:dz};}
function induction(x,velocity,polarity=1,winding=1,N=100){const a=.1,B0=.02,B=polarity*B0*(1+(x/a)**2)**-1.5,dB=-3*polarity*B0*x/a**2*(1+(x/a)**2)**-2.5,flux=B*.003,E=-winding*N*.003*dB*velocity;return{B,flux,E,current:E/10};}
install(5,[choice('winding','코일 감기',['Left turn','Right turn']),toggle('pole','자석 극 반전'),toggle('run','실행',1),toggle('snap','격자에 맞추기',1),control('cursor','관찰 시각',0,8,.05,0,'s')],(v,t)=>{const time=+v.run?t%8:+v.cursor,u=time/8,gs=graphSample(u),x=(gs.position-.2)*.4,velocity=+v.run?gs.velocity*.4:0,sg=+v.pole?-1:1,wind=+v.winding?-1:1,r=induction(x,velocity,sg,wind);let s='';for(let i=0;i<=8;i++)s+=line(40+i*50,55,40+i*50,360,'#dce4df',1);for(let i=0;i<=6;i++)s+=line(40,60+i*50,440,60+i*50,'#dce4df',1);let pd='',ed='';for(let i=0;i<=240;i++){const z=graphSample(i/240),px=40+400*i/240,py=350-z.position*280;pd+=`${i?'L':'M'}${px} ${py}`;if(i/240<=u){const e=induction((z.position-.2)*.4,z.velocity*.4,sg,wind).current;ed+=`${ed?'L':'M'}${px} ${258-e*1500}`;}}s+=group('position-control-graph',path(pd,'#8c999a',3)+path(ed,K.red,3)+line(40+400*u,50,40+400*u,360,K.gold,2)+text(245,28,'자석의 위치와 유도 전류',20)+text(240,390,'시간 (s)',16)+text(65,420,'회색: 위치를 끌어 조절',15,K.wire,'start')+text(420,420,'빨강: 전류',15,K.red));graphPoints.forEach((p,i)=>{s+=`<g style="touch-action:none;cursor:grab" data-graph-point="${i}" data-node="graph-point-${i}" tabindex="0" role="slider" aria-label="${i*2}초 자석 위치" aria-valuenow="${p}">`+circle(40+i*100,350-p*280,9,'white','#7d9392',3)+'</g>';});const my=310-gs.position*230;s+=group('vertical-magnet-and-coil',path('M562 278V365H742V215H612',K.wire,3)+`<g transform="rotate(90 590 285)">`+solenoid(590,285,90,48,7,!!+v.winding)+'</g>'+bar(590,my,96,32,!!+v.pole,90)+meter(742,280,r.current*150,32)+arrow(652,my,652,my-velocity*250,K.muted,3)+text(660,400,'세로로 움직이는 자석',16));return{svg:s,metrics:[metric('격자 맞춤',+v.snap?'켜짐':'꺼짐'),metric('시각',fmt(time,2),'s'),metric('자석 위치',fmt(x*100,2),'cm'),metric('자석 속도',fmt(velocity),'m/s'),metric('유도 전압',fmt(r.E,5),'V'),metric('유도 전류',fmt(r.current*1000,3),'mA')],explanation:'왼쪽 회색 그래프의 점을 움직이면 오른쪽 자석의 세로 위치 이력이 바뀝니다. 같은 그래프를 따라 이동하면서 ε=−N dΦ/dt인 전압과 닫힌 코일의 전류가 계산됩니다.',question:'자석이 가까이 있지만 위치 그래프가 수평이면?',answer:'위치가 변하지 않아 자속 변화율과 유도 전류가0입니다.',note:'N=100회, 코일 면적30cm², 저항10Ω. 원본과 같은 그래프 제어/세로 장치의 관계를 복원했으며 곡선 보간과 수치 축척은 독립 모형입니다. 실행을 끄면 자석을 정지시키므로 전류는0입니다. 그래프의 빨간 과거 이력은 설정된 운동에 대한 예측값입니다.'};},{reset(){graphPoints=[.85,.85,.2,.2,.85];graphDrag=null;},snapshot(){return[{label:'위치 그래프',value:graphPoints.join(',')}];},onScenePointer(e,svg,paint){if(e.type==='pointerdown'){const el=e.target.closest?.('[data-graph-point]');if(!el)return;graphDrag=+el.dataset.graphPoint;svg.setPointerCapture?.(e.pointerId);e.preventDefault?.();}if(graphDrag!==null&&(e.type==='pointermove'||e.type==='pointerdown')){let p=coords(e,svg),z=clamp((350-p.y)/280,.05,.95),snap=typeof document!=='undefined'?document.querySelector('#controls [data-key="snap"]')?.value==='1':true;graphPoints[graphDrag]=snap?Math.round(z*20)/20:z;paint();}if(e.type==='pointerup'||e.type==='pointercancel'){graphDrag=null;svg.releasePointerCapture?.(e.pointerId);}},onSceneKeyDown(e,svg,paint){const el=e.target.closest?.('[data-graph-point]');if(el&&['ArrowUp','ArrowDown'].includes(e.key)){let i=+el.dataset.graphPoint;graphPoints[i]=clamp(graphPoints[i]+(e.key==='ArrowUp'?.05:-.05),.05,.95);e.preventDefault();paint();}},graphSample,induction});
// 6. Horizontal coil, battery below, all-space test compass matrix.
install(6,[toggle('reverse','전류 방향 전환'),toggle('winding','감은 방향 전환'),choice('mode','표시',['나침반','화살표']),toggle('hand','오른손의 법칙'),toggle('current','전류 표시',1)],v=>{const I=+v.reverse?-2:2,sign=Math.sign(I)*(+v.winding?-1:1);let s=group('coil-compass-matrix',matrix((x,y)=>dipole(x,y,400,200,sign,0),(x,y)=>Math.abs(x-400)<125&&Math.abs(y-200)<62||Math.abs(x-400)<65&&Math.abs(y-325)<30,!+v.mode,32,24,780,28,410));s+=group('coil-and-battery-below',path('M285 200V325H348M515 200V325H452',K.wire,3)+solenoid(400,200,205,100,11,!!+v.winding)+battery(400,325,false,!!+v.reverse));if(+v.current)s+=arrow(+v.reverse?340:460,325,+v.reverse?315:485,325,K.red,3)+arrow(303,I>0?180:220,303,I>0?220:180,K.red,3);if(+v.hand)s+=rightHand(560,215,sign,false);return{svg:s,metrics:[metric('코일 축 방향',sign>0?'오른쪽':'왼쪽'),metric('감은 방향',+v.winding?'반대':'기본')],explanation:'코일과 바로 아래 전지를 유지한 채 주변 모든 위치의 나침반을 비교합니다. 전류 또는 감은 방향 하나를 바꾸면 축 방향 자기장이 반전하고, 둘 다 바꾸면 원래 방향입니다.',note:'공심 코일의 외부 방향은 쌍극자 근사입니다. 실제 나침반의 마찰과 감쇠, 코일의 누설장 세기는 계산하지 않습니다. 오른손 엄지는 코일 축 자기장, 굽힌 손가락은 전류 방향입니다.'};});
function rightHand(x,y,sign=1,vertical=true){const rot=vertical?(sign>0?0:180):(sign>0?90:-90);return group('right-hand-rule',`<g transform="translate(${x} ${y}) rotate(${rot})">`+path('M-12 34Q-34 30 -34 9L-34 -16Q-34 -28 -23 -26L-12 -18V-51Q-12 -66 0 -64Q10 -63 9 -50V-5L20 -9Q33 -9 34 3L34 25Q27 45 9 43Z','#bb9e82',2,'#ecd9bd')+arrow(0,-23,0,-70,K.red,3)+path('M-26 7Q-5 -5 24 7M-26 17Q-5 5 24 17M-23 27Q-5 15 20 27',K.green,2)+'</g>');}
// 7. Horizontal entry/exit is deliberately different from ID5's vertical motion graph.
install(7,[control('motion','자석 왕복 운동',0,3,.1,1),control('rotation','자석 회전 운동',0,3,.1,0),choice('winding','코일 감기',['Right turn','Left turn']),choice('load','관찰 장치',['전구','검류계']),toggle('field','자기장 표시',1),toggle('current','유도 전류 표시',1)],(v,t)=>{const w=+v.motion*.8,a=+v.rotation*t,px=260+(+v.motion?120*Math.sin(w*t):0),x=(px-565)/600,vel=+v.motion?120*w*Math.cos(w*t)/600:0,p=Math.cos(a),r=induction(x,vel,p,+v.winding?-1:1),rotationE=(+v.winding?-1:1)*100*.003*.02*(1+(x/.1)**2)**-1.5*Math.sin(a)*+v.rotation,E=r.E+rotationE,I=E/10;let s='';if(+v.field)s+=matrix((x0,y)=>dipole(x0,y,px,235,-Math.cos(a),-Math.sin(a)),(x0,y)=>Math.abs(x0-px)<80&&Math.abs(y-235)<40,false,38,30,760,80,390);s+=group('horizontal-magnet-entry',bar(px,235,150,48,false,a/RAD)+solenoid(565,235,145,110,9,!!+v.winding)+path('M492 235V112H538M638 235V112H592',K.wire,3));s+=group('replaceable-load-above-coil',+v.load?meter(565,112,I*1200,29):lamp(565,112,Math.abs(I)>.00003,29));if(+v.current&&Math.abs(I)>1e-9)s+=arrow(I>0?515:542,112,I>0?542:515,112,K.red,4);if(Math.abs(vel)>.001)s+=arrow(px,330,px+Math.sign(vel)*70,330,K.muted,3);s+=text(250,415,'자석: 가로 이동과 회전을 따로 조절',18)+text(590,415,'같은 자리의 전구 / 검류계',17);return{svg:s,metrics:[metric('자석 속도',fmt(vel),'m/s'),metric('유도 전압',fmt(E,6),'V'),metric('유도 전류',fmt(I*1000,4),'mA')],explanation:'왼쪽 자석이 오른쪽 코일로 들어가고 나옵니다. 이동이나 회전 때문에 자속이 바뀌면 코일 바로 위 장치에 전류가 흐릅니다.',question:'왕복과 회전 운동을 모두0으로 놓으면?',answer:'자석이 있어도 자속이 변하지 않으므로 유도 전류는0입니다.',note:'이동/회전의 자속 변화율을 함께 계산한 작은 코일 근사입니다. 자속은 자석 방향의 cos성분을 사용하며 부하10Ω, 자기 유도와 부하 역작용은 생략합니다. 그림의 운동 축척은 실제 치수와 다릅니다.'};});
// 20. Wire arch stands perpendicular to a perspective compass board; return circuit is below.
function circularField(x,y,I=1){let bx=0,by=0,bz=0;for(let k=0;k<160;k++){const a=(k+.5)*TAU/160,px=Math.cos(a),pz=Math.sin(a),dx=-Math.sin(a)*TAU/160,dz=Math.cos(a)*TAU/160,rx=x-px,ry=y,rz=-pz,r=Math.pow(rx*rx+ry*ry+rz*rz+.015,1.5);bx+=-dz*ry/r;by+=(dz*rx-dx*rz)/r;bz+=dx*ry/r;}return[bx*I,by*I,bz*I];}
install(20,[toggle('reverse','전류 방향 전환'),toggle('wire','도선 위치 표시',1),toggle('hand','오른손의 법칙')],v=>{const I=+v.reverse?-1:1;let s=path('M255 260V352H348M545 260V352H452',K.wire,4)+resistor(255,307,true)+battery(400,352,false,!!+v.reverse);s+=group('horizontal-compass-board',path('M140 210L650 210L720 315L210 315Z','#c0cdca',2,'#ffffff'));for(let yy=-1;yy<=1.001;yy+=.4)for(let xx=-1.8;xx<=1.801;xx+=.35){if(Math.abs(Math.abs(xx)-1)<.2&&Math.abs(yy)<.25)continue;let b=circularField(xx,yy,-I),cx=400+135*xx+32*yy,cy=260+43*yy;s+=compass(cx,cy,135*b[0]+32*b[1],43*b[1],9);}s+=group('upright-wire-arch',path('M255 260C255 35 545 35 545 260',K.wire,7)+arrow(280,I>0?180:145,294,I>0?145:180,K.red,3));if(+v.wire)s+=circle(255,260,10,'none',K.red,2)+circle(545,260,10,'none',K.red,2);if(+v.hand)s+=rightHand(600,145,I,false);s+=text(400,411,'세워진 원형 도선 · 수평 나침반 판 · 아래쪽 전지',18);return{svg:s,metrics:[metric('전류 방향',I>0?'기본':'반대'),metric('나침반 판','도선 면과 수직')],explanation:'반원형 도선이 나침반 판 위로 솟아 있습니다. 도선이 판을 통과하는 두 지점과 판 위 나침반 방향을 연결해 보세요. 전지를 뒤집으면 전류와 모든 나침반 방향이 함께 반전됩니다.',question:'도선의 양쪽 통과 지점에서 나침반이 같은 방향으로 원을 그리나요?',answer:'두 지점의 전류가 판을 통과하는 방향이 반대이므로 주위 자기장 회전 방향도 반대입니다.',note:'나침반은 수직 원형 전류의 Biot–Savart장을 수평 판에 투영한 방향을 가리킵니다. 회로의 바깥 연결선과 전지의 자기장은 생략했습니다. 도선 바로 옆의 수학적 발산은 완화했습니다.'};});
