install(36,[choice('depth','나침반의 위치',['전선 위','전선 아래']),choice('battery','전지의 방향',['세로: 연결 안 됨','가로: + 왼쪽','가로: + 오른쪽']),choice('display','흐름 표시',['감추기','전류','전자'])],v=>{const connected=+v.battery!==0,I=+v.battery===1?3:+v.battery===2?-3:0,depth=+v.depth?-1:1,b=I*12*depth,earth=25,theta=Math.atan2(-b,earth),cx=400,cy=130;let s=group('rectangular-oersted-circuit',path('M180 130V200M180 270V355H348M452 355H660V130',K.wire,5)+resistor(180,235,true,70)+battery(400,355,!connected,+v.battery===1));const needle=group('compass-at-top-wire',circle(cx,cy,65,'#f7f5e9','#a3b3b3',3)+line(cx-58,cy,cx+58,cy,'#c6d0ca',1)+line(cx,cy-58,cx,cy+58,'#c6d0ca',1)+compass(cx,cy,earth,-b,56,true)+circle(cx,cy,4,K.ink,K.ink));const top=group('horizontal-top-wire',line(180,130,660,130,K.wire,5));s+=+v.depth?needle+top:top+needle;s+=group('cardinal-guide',text(735,106,'W',17)+text(735,175,'E',17)+text(692,143,'S',17)+text(774,143,'N',17)+line(706,138,763,138,'#a7b9b6',1)+line(735,114,735,158,'#a7b9b6',1));if(+v.display&&connected){const sign=I*Math.sign(+v.display===2?-1:1);s+=arrow(sign>0?235:310,130,sign>0?310:235,130,+v.display===2?K.blue:K.red,4)+arrow(660,sign>0?230:300,660,sign>0?300:230,+v.display===2?K.blue:K.red,4);}s+=text(400,425,connected?'전지의 방향과 나침반의 위·아래를 각각 바꿔 비교':'세로 전지는 양 끝이 연결되지 않아 전류0',18);return{svg:s,metrics:[metric('회로 전류',I,'A'),metric('북쪽(오른쪽)에서 편향',fmt(theta/RAD,1),'°'),metric('나침반 위치',+v.depth?'전선 아래':'전선 위')],explanation:'전선은 위쪽에서 가로로 지나고 나침반의 북쪽은 오른쪽입니다. 나침반을 전선의 반대쪽 깊이로 옮기거나 전지 하나만 뒤집으면 전선에 의한 자기장이 반전됩니다.',question:'전지가 세로로 돌아가 회로에서 끊어지면?',answer:'전류가0이 되어 나침반은 지구 자기장인 오른쪽 북쪽을 가리킵니다.',note:'원본의 가로 전선/나침반 깊이와 회전 전지 관계를 유지합니다. 지구 수평장25μT, 도선장12μT/A의 정성적 기하 모형으로 전선이 나침반 위·아래에 있을 때 부호를 반전합니다.'};});
