install(75,[control('I','전류 세기',0,8,.25,3,'A'),toggle('reverse','전류 방향 전환'),toggle('hand','오른손의 법칙'),toggle('compass','나침반')],v=>{const I=+v.I*(+v.reverse?-1:1);let s='';for(let k=0;k<2;k++){const x=30+400*k,wx=x+255,cy=235;let g=path(`M${x+32} 100H${x+122}M${x+188} 100H${wx}V370H${x+32}V290M${x+32} 190V100`,K.wire,4)+resistor(x+155,100,false,66)+battery(x+32,240,true,I<0);if(k===0){g+=path(`M${wx-104} ${cy-35}L${wx+60} ${cy-35}L${wx+103} ${cy+55}L${wx-62} ${cy+55}Z`,'#b5c5c2',2,'white');for(let r=25;r<=78;r+=13){g+=ellipse(wx,cy+7,r,r*.38,'#b5c5bc',1);for(let i=0;i<26;i++){const a=i*TAU/26+.12*r,xx=wx+r*Math.cos(a),yy=cy+7+r*.38*Math.sin(a),aa=Math.atan2(.38*Math.cos(a),-Math.sin(a));g+=line(xx-2*Math.cos(aa),yy-2*Math.sin(aa),xx+2*Math.cos(aa),yy+2*Math.sin(aa),I?'#718d7a':'#bdc7c1',1.1);}}if(+v.compass){const bx=I*wireCompass.dy/.38,by=-I*.38*wireCompass.dx;g+=`<g style="touch-action:none;cursor:grab" data-wire-compass="1" data-node="wire-compass" tabindex="0" role="slider" aria-label="종이 위 나침반 이동">`+(I?compass(wx+wireCompass.dx,cy+7+wireCompass.dy,bx,by,15):circle(wx+wireCompass.dx,cy+7+wireCompass.dy,15,'white','#a5b9ad',1)+text(wx+wireCompass.dx,cy+12+wireCompass.dy,'?',14))+'</g>'; }}else if(I){for(let r of [35,61,85]){g+=ellipse(wx,cy+7,r,r*.38,K.green,2);g+=arrow(wx-r,I>0?cy+4:cy+10,wx-r,I>0?cy+10:cy+4,K.green,2);}}g+=line(wx,105,wx,370,K.wire,5);if(I)g+=arrow(wx,I>0?190:130,wx,I>0?130:190,K.red,5);if(k===1&&+v.hand)g+=rightHand(wx-35,255,I>=0?1:-1,true);g+=text(x+190,420,k?'같은 전류 · 오른손의 법칙':'철가루 · 수평 종이 위의 나침반',17);s+=group(k?'wire-rule-apparatus':'wire-filings-apparatus',g);}return{svg:s,metrics:[metric('두 회로의 전류',fmt(Math.abs(I)),'A'),metric('위에서 본 자기장',I>0?'반시계':I<0?'시계':'도선장 없음')],explanation:'두 회로의 세로 전선에 같은 전류가 흐릅니다. 왼쪽은 수평 종이 위 철가루와 나침반, 오른쪽은 전류 화살표와 오른손의 법칙으로 같은 자기장을 보여 줍니다.',question:'오른손에서 엄지와 굽힌 손가락은 각각 무엇을 뜻하나요?',answer:'엄지는 전류, 굽힌 손가락은 전선 주위를 도는 자기장입니다. 전류가 위쪽이면 위에서 본 자기장은 반시계 방향입니다.',note:'종이 위 동심원은 긴 직선 도선 근사입니다. 전류0에서는 도선장이 사라지며 철가루의 남은 배열은 실제 재배치가 아니라 위치 안내입니다. 나침반 방향은 지구 자기장을 생략한 도선장만 표시합니다.'};},{reset(){wireCompass={dx:-18,dy:38,drag:false};},onScenePointer(e,svg,paint){if(e.type==='pointerdown'&&e.target.closest?.('[data-wire-compass]')){wireCompass.drag=true;svg.setPointerCapture?.(e.pointerId);}if(e.type==='pointermove'&&wireCompass.drag){const p=coords(e,svg);wireCompass.dx=clamp(p.x-285,-70,70);wireCompass.dy=clamp(p.y-242,-27,43);paint();}if(e.type==='pointerup'||e.type==='pointercancel')wireCompass.drag=false;},onSceneKeyDown(e,svg,paint){if(!e.target.closest?.('[data-wire-compass]')||!e.key.startsWith('Arrow'))return;wireCompass.dx=clamp(wireCompass.dx+(e.key==='ArrowRight'?5:e.key==='ArrowLeft'?-5:0),-70,70);wireCompass.dy=clamp(wireCompass.dy+(e.key==='ArrowDown'?4:e.key==='ArrowUp'?-4:0),-27,43);e.preventDefault();paint();}});
// 30. Preserve the enormous Sun at left, small Earth at right, deflection and polar entry.
install(30,[control('cme','CME 세기',0,3,.1,1),toggle('field','지구 자기장',1),toggle('magnet','지구를 자석으로 보기')],(v,t)=>{const cx=640,cy=230,r=36;let s=rect(0,0,800,450,'#111c26','none',0)+circle(-76,230,205,'#eaa84d','#f4cb79',4);for(let i=0;i<7;i++)s+=circle(-76,230,209+i*5,'none',`rgba(232,158,68,${.17-i*.02})`,4);s+=text(68,235,'태양',24,'#fff2cd');if(+v.field){s+=path('M796 70C660 70 540 90 530 230C540 370 660 390 796 390',K.green,2);for(const side of [-1,1])for(let n=0;n<4;n++)s+=path(`M120 ${150+n*25}C360 ${150+n*25} 500 ${230+side*(120+n*12)} 640 ${230+side*39}`,'#8ea9ac',1.2);}for(let j=0;j<24;j++){const y=30+j*17,phase=((t*(40+v.cme*45)+j*53)%650),x=150+phase;let yy=y;if(+v.field&&x>470){const delta=y-cy,deflect=(1-Math.exp(-Math.max(0,x-470)/60))*70*Math.exp(-Math.abs(delta)/160);yy=y+Math.sign(delta||1)*deflect;}if(Math.hypot(x-cx,yy-cy)>r)s+=line(x,yy,x+8+v.cme*5,yy,'#dae2dd',1.4);}s+=group('earth-at-right',circle(cx,cy,r,'#79a9c9','#a4cde5',1)+path(`M${cx-22} 210Q${cx+8} 198 ${cx+17} 229L${cx-4} 252L${cx-18} 235`,K.green,10));if(+v.field)for(const side of [-1,1])s+=ellipse(cx,cy+side*29,26,6,'#86d5aa',4,'#87d6bb44');if(+v.magnet)s+=bar(cx,cy,68,22,true,90);s+=text(400,417,+v.field?'태양풍 일부가 극지방으로 유입 · 대기와 상호작용하여 오로라':'자기장 끄기: 자기적 차폐와 극지방 유도 경로 없음',16,'#d3e7e4');return{svg:s,metrics:[metric('CME 상대 세기',fmt(+v.cme,1)),metric('지구 자기장',+v.field?'있음':'없음')],explanation:'태양에서 나온 입자가 왼쪽에서 오른쪽으로 이동합니다. 지구 자기장은 태양풍 흐름을 바꾸고 일부 입자를 극지방으로 안내합니다. 대기와의 상호작용이 빛을 냅니다.',question:'극 부근에서 오로라가 잘 보이는 까닭은?',answer:'자기장을 따라 이동한 일부 입자가 극지방 상층 대기에 에너지를 전달하기 때문입니다.',note:'Sun→Earth의 크기 차이와 입자 경로를 보존한 정성 모형입니다. 실제 크기·거리·속도 비율, 자기 재결합, 태양풍 이온/전자 궤도 및 오로라 밝기를 수치 예측하지 않습니다. CME 슬라이더는 표시 흐름의 세기를 바꿉니다.'};});
